{
  "root_cause": "The navigation controller's `navigate` function is called each time `autoComplete.start` renders a new results list. The original code used a closure variable `currentFocus` that persisted across renders because a guard flag (`_navListenerAttached`) prevented duplicate listeners but did not reset the focus index. When the list was re-filtered (e.g., after typing "l"), the stale `currentFocus` value caused ArrowDown to target an out-of-bounds index, and `update` set `aria-activedescendant` using the unclamped index before `addActive` clamped it.",
  "repair_strategy": "Store the focus index on the input field (`_currentFocus`) so it can be reset to -1 on every render. Update `update`, `addActive`, and `navigation` to read/write this shared property. Keep the `_navListenerAttached` guard to prevent duplicate keydown listeners. This ensures the focus index resets when the suggestion list changes, and `aria-activedescendant`/`aria-selected` always reflect the clamped index.",
  "edits": [
    {
      "path": "src/controllers/navigationController.js",
      "sha256": "cb38337c041e8e0543c4f7b31666374956d6dc85011604e12ff127c9bf67ddde",
      "before": "import { closeAllLists } from "./listController";
import eventEmitter from "../utils/eventEmitter";

/**
 * List navigation function initializer
 *
 * @param {Object} config - autoComplete configurations
 * @param {Object} dataFeedback - The available data object
 *
 */
const navigate = (config, dataFeedback) => {
  // Reset focus state
  let currentFocus = -1;

  /**
   * Update list item state
   *
   * @param {Object} event - The `keydown` event Object
   * @param {Array <elements>} list - The array of list items
   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...dataFeedback, selection: dataFeedback.results[currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (currentFocus >= list.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = list.length - 1;
    // Add "active" class to the item
    list[currentFocus].setAttribute("aria-selected", "true");
    list[currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigate);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[currentFocus].click();
      }
    }
  };

  const navigate = config.resultsList.navigation || navigation;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  config.inputField.addEventListener("keydown", navigate);
};

export { navigate };",
      "after": "import { closeAllLists } from "./listController";
import eventEmitter from "../utils/eventEmitter";

/**
 * List navigation function initializer
 *
 * @param {Object} config - autoComplete configurations
 * @param {Object} dataFeedback - The available data object
 *
 */
const navigate = (config, dataFeedback) => {
  // Reset focus state on each render
  config.inputField._currentFocus = -1;

  /**
   * Update list item state
   *
   * @param {Object} event - The `keydown` event Object
   * @param {Array <elements>} list - The array of list items
   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      config.inputField._currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      config.inputField._currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[config.inputField._currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...dataFeedback, selection: dataFeedback.results[config.inputField._currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (config.inputField._currentFocus >= list.length) config.inputField._currentFocus = 0;
    if (config.inputField._currentFocus < 0) config.inputField._currentFocus = list.length - 1;
    // Add "active" class to the item
    list[config.inputField._currentFocus].setAttribute("aria-selected", "true");
    list[config.inputField._currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigate);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (config.inputField._currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[config.inputField._currentFocus].click();
      }
    }
  };

  const navigateFn = config.resultsList.navigation || navigation;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  if (!config.inputField._navListenerAttached) {
    config.inputField.addEventListener("keydown", navigateFn);
    config.inputField._navListenerAttached = true;
  }
};

export { navigate };"
    }
  ],
  "expected_accessibility_effect": "Keyboard users will reliably move focus through suggestions with ArrowDown/ArrowUp, and pressing Enter will commit the currently highlighted suggestion. The `aria-selected` and `aria-activedescendant` attributes will always match the visible selection, even after the suggestion list is re-filtered.",
  "functional_risks": [
    "If a custom `navigation` function is provided via `resultsList.navigation`, it will not receive the shared `_currentFocus` property and may behave differently.",
    "The `_currentFocus` property persists on the input field across autoComplete instances if the same input is re-used; this is mitigated by resetting it on each `navigate` call."
  ],
  "verification_requirements": [
    "After typing "bl" then pressing ArrowDown once and Enter, the input value must be "Blackberry".",
    "ArrowDown and ArrowUp should correctly wrap and update `aria-activedescendant` and `aria-selected` on the appropriate list item.",
    "Escape should clear the input and close the suggestion list.",
    "Tab should behave as an arrow down when the list is open and move focus away when closed.",
    "Re-filtering the list (e.g., typing additional characters) resets the highlight to the first item."
  ]
}

